"use client";
import { useEffect,useState } from "react";import { useParams,useRouter } from "next/navigation";import { useUser } from "@/context/UserContext";import { graphqlRequest } from "@/lib/graphql";import { uploadImage,type UploadedMedia } from "@/lib/upload";import styles from "./profile.module.css";
type Profile={id:string;name:string;username:string;email:string;profilePicture?:string|null;accountType:string;subscription:{plan:string;status:string;autoRenew:boolean}};
const FIELDS="id name username email profilePicture accountType subscription { plan status autoRenew }";
export default function ProfilePage(){const {username}=useParams<{username:string}>();const router=useRouter();const {authenticatedUser,authToken,authLoading,updateAuthenticatedUser}=useUser();const [profile,setProfile]=useState<Profile|null>(null);const [name,setName]=useState("");const [media,setMedia]=useState<UploadedMedia|null>(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState("");const own=authenticatedUser?.username===username;
useEffect(()=>{graphqlRequest<{user:Profile|null}>(`query($username:String!){user(username:$username){${FIELDS}}}`,{username},authToken).then(({user})=>{setProfile(user);setName(user?.name??"");}).catch(e=>setMessage(e.message));},[username,authToken]);
if(authLoading||!profile)return <main className={styles.page}><p>{message||"Carregando perfil…"}</p></main>;
async function select(file?:File){if(!file)return;setBusy(true);setMessage("");try{setMedia(await uploadImage(file,"USER_AVATAR"));}catch(e){setMessage(e instanceof Error?e.message:"Falha no upload.");}finally{setBusy(false);}}
async function save(){setBusy(true);try{const {updateMyProfile}=await graphqlRequest<{updateMyProfile:Profile}>(`mutation($data:UpdateProfileInput!){updateMyProfile(data:$data){${FIELDS}}}`,{data:{name,profilePictureID:media?.id}},authToken);setProfile(updateMyProfile);updateAuthenticatedUser(updateMyProfile as any);setMedia(null);setMessage("Perfil atualizado.");router.refresh();}catch(e){setMessage(e instanceof Error?e.message:"Falha ao salvar.");}finally{setBusy(false);}}
return <main className={styles.page}><section className={styles.card}><div className={styles.header}>{/* eslint-disable-next-line @next/next/no-img-element */}<img src={media?.url||profile.profilePicture||"/image-placeholder.svg"} alt="Foto de perfil"/><div><h1>{profile.name}</h1><p>@{profile.username}</p><span>{profile.subscription.plan}</span></div></div>{own&&<div className={styles.form}><label>Foto de perfil<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={e=>void select(e.target.files?.[0])}/></label><label>Nome<input value={name} maxLength={120} onChange={e=>setName(e.target.value)}/></label><label>E-mail<input value={profile.email} disabled/></label><button onClick={save} disabled={busy||name.trim().length<2}>{busy?"Salvando…":"Salvar alterações"}</button>{message&&<p>{message}</p>}</div>}</section></main>}
